  const checklists={
    Matematik:['Tanım kümesini ve özel koşulları yazdım.','Kullandığım bağıntının neden geçerli olduğunu kontrol ettim.','Sonucu denklemde veya grafikte geri sınadım.'],
    'Türk Dili ve Edebiyatı':['Dönem, tür ve anlatım tekniğini ayırdım.','Yargımı metindeki bir ipucuyla destekledim.','Benzer topluluk ya da türlerle farkını kurdum.'],
    Fizik:['Sistemi ve yön kabulünü çizdim.','Birimleri SI sistemine çevirdim.','Sonucun yönünü ve fiziksel anlamını kontrol ettim.'],
    Kimya:['Tanecik, mol ve yük dengesini kontrol ettim.','Koşulları ve tepkime türünü belirledim.','Sonucu birim ve işaret bakımından sınadım.'],
    Biyoloji:['Olayın gerçekleştiği yapı ve basamağı belirledim.','Madde, enerji ve bilgi akışlarını ayırdım.','İstisna gibi görünen ifadeyi temel ilkeyle kontrol ettim.'],
    'T.C. İnkılap Tarihi ve Atatürkçülük':['Olayı kronolojiye yerleştirdim.','Neden, gelişme ve sonucu birbirinden ayırdım.','Kararı ilgili ilke ve uluslararası koşulla ilişkilendirdim.'],
    Coğrafya:['Mekânı ve ölçeği belirledim.','Doğal ve beşerî etkenleri birlikte değerlendirdim.','Harita ya da grafikteki veriyi yorumla destekledim.'],
    'Felsefe Grubu ve Din Kültürü':['Kavramın tanımını iddiadan ayırdım.','Gerekçe ile sonucu belirledim.','Seçeneği metnin ana ilkesiyle karşılaştırdım.']
  };

  add('Matematik','Üstel ve Logaritmik Fonksiyonlar','Üstel fonksiyonda değişken üstte bulunur: f(x)=a^x için a pozitif ve 1’den farklıdır. Fonksiyonun tanım kümesi gerçek sayılar, değer kümesi pozitif gerçek sayılardır. Logaritma bu fonksiyonun tersidir; log_a(b)=c ifadesi a^c=b anlamına gelir. Çarpım, bölüm ve kuvvet kuralları yalnızca logaritmanın içindeki ifadeler pozitifken uygulanır. Denklem çözerken cebirsel çözüm kadar tanım koşulu da sonucun parçasıdır.',['Terslik|a^x ve log_a(x) grafikleri y=x doğrusuna göre simetriktir.','Taban|a>1 ise üstel fonksiyon artan; 0<a<1 ise azalandır.','Tanım|log_a(g(x)) yazılabilmesi için g(x)>0 olmalıdır.','Dönüşüm|log_a(b)=ln(b)/ln(a) taban değiştirme bağıntısıdır.'],'log₂(x−1)+log₂(x−3)=3 denklemini çöz.',['Önce x−1>0 ve x−3>0 koşullarından x>3 bulunur.','Toplama kuralıyla log₂((x−1)(x−3))=3 ve (x−1)(x−3)=8 yazılır.','x²−4x−5=0 denkleminin adayları 5 ve −1’dir; tanım koşulunu yalnız 5 sağlar.'],'Logaritma kurallarını tanım koşulunu yazmadan uygulamak, geçersiz kökleri çözüme katabilir.',{type:'curve',title:'Üstel ve logaritmik fonksiyonların terslik ilişkisi',items:['y=aˣ','y=x','y=logₐx']});
  add('Matematik','Diziler','Dizi, terimleri pozitif tam sayılarla sıralanan bir fonksiyon gibi düşünülebilir. Aritmetik dizide ardışık iki terim arasındaki fark d; geometrik dizide oran r sabittir. Genel terim, tek tek yazmadan istenen sıradaki değeri verir. Toplam bağıntıları ise ilk terim, terim sayısı ve fark ya da oran birlikte belirlendikten sonra kullanılmalıdır. Özyinelemeli tanım bir terimi öncekine bağlarken açık tanım n’inci terimi doğrudan verir.',['Aritmetik|a_n=a₁+(n−1)d.','Geometrik|a_n=a₁·r^(n−1).','Toplam|Aritmetik dizide S_n=n(a₁+a_n)/2.','Oran|Geometrik toplamda r=1 durumu ayrıca değerlendirilir.'],'a₁=5 ve ortak farkı 3 olan aritmetik dizinin 10. terimini ve ilk 10 terim toplamını bul.',['a₁ ve d belirlenir: 5 ve 3.','a₁₀=5+9·3=32 bulunur.','S₁₀=10·(5+32)/2=185 olur.'],'Terim numarası n ile artış sayısını karıştırmak sık hatadır; ilk terimden n’inci terime n−1 adım vardır.',{type:'bars',title:'Aritmetik dizide sabit artış',items:['5','8','11','14','17']});
  add('Matematik','Trigonometri','Trigonometri, açı ile birim çember üzerindeki noktanın koordinatlarını ilişkilendirir. cos x yatay, sin x düşey koordinattır; tan x=sin x/cos x bağıntısı cos x sıfır değilken geçerlidir. Derece ve radyan aynı açının farklı ölçüleridir; 180°=π radyandır. Periyodiklik denklemlerde birden fazla çözüm üretir. Özdeşlikler eşitliğin tanımlı olduğu tüm değerlerde, denklemler ise yalnız belirli değerlerde doğrudur.',['Birim çember|P(cos x,sin x) noktası açının işaretlerini gösterir.','Temel özdeşlik|sin²x+cos²x=1.','Periyot|Sinüs ve kosinüsün temel periyodu 2π, tanjantın π’dir.','Bölge|İşaret, açının bulunduğu bölgeye göre belirlenir.'],'0≤x<2π aralığında sin x=√3/2 denklemini çöz.',['Referans açı π/3’tür.','Sinüs I ve II. bölgede pozitif olduğundan x=π/3 ve x=2π/3 seçilir.','İki değer de verilen aralıktadır.'],'Ters trigonometrik fonksiyonun verdiği tek ana değeri, periyodik denklemin bütün çözümleri sanmak eksik sonuç üretir.',{type:'flow',title:'Açıdan çözüme',items:['Referans açı','İşaret bölgeleri','Periyot','Aralık kontrolü']});
  add('Matematik','Dönüşümler ve Analitik Geometri','Bir grafiği dönüştürmek, her noktayı belirli bir kurala göre yeni konuma taşımaktır. y=f(x−h)+k ifadesi grafiği h birim sağa ve k birim yukarı taşır; parantez içindeki işaret yatay yönle ters görünür. Noktanın eksenlere göre yansıması koordinat işaretlerini değiştirir. Doğru denklemlerinde eğim, iki noktadaki değişim oranıdır; paralel doğruların eğimleri eşit, dik doğruların eğim çarpımı uygun koşullarda −1’dir.',['Öteleme|f(x−h)+k: sağa h, yukarı k.','Yansıma|f(−x) y eksenine; −f(x) x eksenine yansımadır.','Eğim|m=(y₂−y₁)/(x₂−x₁).','Sıra|Farklı dönüşümlerin uygulanma sırası sonucu değiştirebilir.'],'y=x² grafiğini 2 birim sağa ve 3 birim yukarı ötele; yeni tepe noktasını bul.',['Sağa öteleme için x yerine x−2 yazılır.','Yukarı öteleme için ifadeye 3 eklenir: y=(x−2)²+3.','Başlangıçtaki (0,0) tepe noktası (2,3) olur.'],'Yatay ötelemede parantez içindeki işareti grafik yönüyle aynı sanmak, sağ-sol yönünü ters kurar.',{type:'compare',title:'Temel grafik dönüşümleri',items:['f(x−h): sağa','f(x)+k: yukarı','f(−x): y eksenine yansıma']});
  add('Matematik','Limit ve Süreklilik','Limit, x bir değere yaklaşırken fonksiyon çıktısının hangi değere yöneldiğini inceler; noktanın kendisindeki değer farklı veya tanımsız olabilir. İki taraflı limitin varlığı için sağdan ve soldan limitlerin eşit olması gerekir. Bir fonksiyonun x=a noktasında sürekli olması için f(a) tanımlı olmalı, limit var olmalı ve bu iki değer eşit olmalıdır. Belirsiz görünüm doğrudan sonuç değil, ifadeyi sadeleştirme veya farklı yöntem kullanma işaretidir.',['Yaklaşım|Limit, noktadaki değerden çok çevredeki davranışı ölçer.','Tek yön|Sağ ve sol limitler ayrı ayrı incelenebilir.','Süreklilik|lim x→a f(x)=f(a) üç koşulu birlikte özetler.','Belirsizlik|0/0 sadeleştirme gerektiren bir biçimdir.'],'lim x→3 (x²−9)/(x−3) değerini bul.',['Doğrudan yerine koyma 0/0 biçimini verir.','Pay (x−3)(x+3) biçiminde çarpanlara ayrılır ve x≠3 için sadeleşir.','Kalan x+3 ifadesinin 3’e limiti 6’dır.'],'0/0 gördüğünde limit yok demek yanlıştır; bu, daha fazla cebirsel inceleme gerektiğini gösterir.',{type:'curve',title:'Silinebilir süreksizlikte yaklaşım',items:['soldan yaklaşım','a noktasındaki boşluk','sağdan yaklaşım']});
  add('Matematik','Türev','Türev, fonksiyonun bir noktadaki anlık değişim oranıdır ve grafikte teğetin eğimini verir. Türev pozitifse fonksiyon o aralıkta artma, negatifse azalma eğilimindedir. Kritik noktalar türevin sıfır olduğu veya tanımsız kaldığı adaylardır; maksimum ya da minimum oldukları işaret değişimiyle doğrulanır. Optimizasyonda önce koşullardan tek değişkenli amaç fonksiyonu kurulmalı, sonra uygun tanım aralığında türev incelenmelidir.',['Tanım|f′(a), fark oranının limitiyle tanımlanır.','Geometri|f′(a) teğet doğrusunun eğimidir.','Ekstremum|f′ işaretinin +’dan −’ye dönmesi yerel maksimumu gösterir.','Hız|Konumun türevi hız, hızın türevi ivmedir.'],'f(x)=x³−6x²+9x fonksiyonunun kritik noktalarını ve türlerini belirle.',['f′(x)=3x²−12x+9=3(x−1)(x−3) bulunur.','İşaret sırası +, −, + olduğundan x=1’de artıştan azalışa; x=3’te azalıştan artışa geçilir.','x=1 yerel maksimum, x=3 yerel minimumdur; gerekirse f değerleri hesaplanır.'],'Sadece f′(x)=0 denklemini çözmek tür belirlemez; işaret tablosu veya ikinci türev kontrolü gerekir.',{type:'flow',title:'Türevle davranış analizi',items:['f′>0: artan','f′=0: aday','f′<0: azalan','işaret değişimi: tür']});
  add('Matematik','İntegral','Belirsiz integral, türevi verilen fonksiyon ailesini bulur ve bu yüzden sabit C içerir. Belirli integral ise bir aralıktaki yönlü birikimi ölçer; temel teorem, bu değeri bir ilkelle uç noktalar üzerinden hesaplamaya bağlar. Grafik x ekseninin altındaysa katkı negatiftir. Geometrik alan isteniyorsa işaret değiştiren noktalarda aralık bölünür ve parçaların mutlak alanları toplanır. Değişken dönüşümü, zincir kuralını ters yönde kullanır.',['İlkel|F′(x)=f(x) ise ∫f(x)dx=F(x)+C.','Belirli integral|∫_a^b f(x)dx=F(b)−F(a).','Yönlü alan|Eksen altı katkılar negatiftir.','Birikim|İntegral yalnız alan değil, toplam değişim ölçüsüdür.'],'∫₀² (3x²−4x+1) dx değerini hesapla.',['Bir ilkel F(x)=x³−2x²+x olarak bulunur.','Üst uçta F(2)=8−8+2=2, alt uçta F(0)=0’dır.','F(2)−F(0)=2 elde edilir; bu yönlü birikimdir.'],'Belirsiz integralde +C’yi unutmak ve belirli integral sonucunu her zaman geometrik alan sanmak iki ayrı hatadır.',{type:'bars',title:'Yönlü birikimin parçalara ayrılması',items:['pozitif bölge','negatif bölge','net integral']});
  add('Türk Dili ve Edebiyatı','Giriş ve Edebiyatın Bilimlerle İlişkisi','Edebî metin yalnız olay aktaran bir belge değildir; dil, estetik kurgu ve çok anlamlılık yoluyla insan deneyimini yeniden oluşturur. Tarih metnin dönemini, sosyoloji toplumsal yapıyı, psikoloji karakter davranışını, felsefe ise temel düşünce problemlerini yorumlamaya yardım eder. Buna rağmen edebî eserin kurmaca yapısı korunmalıdır. Bir parçayı değerlendirirken yazıldığı dönem ile anlattığı dönemi, yazar ile anlatıcıyı ve gerçek kişi ile kurmaca kişiyi ayırmak gerekir.',['Bağlam|Metnin üretildiği tarihsel ve kültürel koşullardır.','Zihniyet|Bir dönemin değer, inanç ve düşünme biçimlerinin metne yansımasıdır.','Kurmaca|Gerçeklikten yararlansa da sanatçının seçme ve düzenlemesiyle kurulur.','Disiplinlerarasılık|Başka bilimler yorum için veri sağlar; edebî yöntemin yerini almaz.'],'Göçle değişen bir mahalleyi, kahramanın yalnızlığı üzerinden anlatan romanda tarih, sosyoloji ve psikoloji hangi sorularla kullanılır?',['Tarih, olayların hangi dönemde ve hangi koşullarda geçtiğini araştırır.','Sosyoloji, göçün aile ve mahalle ilişkilerini nasıl dönüştürdüğünü inceler.','Psikoloji, değişimin kahramanın duygu ve davranışlarına etkisini açıklar; anlatıcı ile yazar özdeşleştirilmez.'],'Metinde tarihsel olay geçmesini eseri tarih kitabı saymak ya da anlatıcının her sözünü yazarın görüşü kabul etmek tür ve anlatıcı hatasıdır.',{type:'flow',title:'Metni çok boyutlu okuma',items:['Dönem ve zihniyet','Toplumsal yapı','Bireyin iç dünyası','Edebî kurgu']});
  add('Türk Dili ve Edebiyatı','Hikâye','Hikâye; kişi, olay veya durum, zaman, mekân ve anlatıcı öğelerini yoğun bir yapı içinde birleştirir. Olay hikâyesinde merak ve sonuç, durum hikâyesinde gündelik bir kesit ve sezdirme öne çıkabilir. Cumhuriyet döneminde toplumcu gerçekçi metinler toplumsal çatışmalara; bireyin iç dünyasını esas alan metinler psikolojik çözümlemeye; modernist metinler parçalı zaman, bilinç akışı ve güvenilmez anlatıcı gibi tekniklere yönelebilir. Sınıflandırma tek kelimeyle değil, metindeki birden fazla kanıtla yapılır.',['Anlatıcı|Olayı aktaran kurmaca sestir; bakış açısının sınırını belirler.','İç monolog|Kişinin düşüncesi düzenli ve doğrudan verilir.','Bilinç akışı|Çağrışımlar, mantıksal sıra zayıflayarak aktarılır.','Durum hikâyesi|Kesin son yerine yaşamdan bir an ve izlenim öne çıkabilir.'],'Zaman sıçramaları, parçalı cümleler ve kahramanın çağrışımlarını kullanan bir hikâyenin anlatım eğilimini belirle.',['Önce zamanın doğrusal ilerlemediği saptanır.','Parçalı dil ve çağrışım zinciri bilinç akışı tekniğine kanıt olur.','Bu göstergeler modernist anlatım olasılığını güçlendirir; yalnız konuya bakılarak karar verilmez.'],'İç monolog ile bilinç akışını aynı kabul etmek yanlıştır; ikincisinde çağrışım ve dil düzeni daha parçalı olabilir.',{type:'compare',title:'Hikâyede anlatım yolları',items:['Olay: merak ve sonuç','Durum: kesit ve sezdirme','Modernist: parçalı algı']});
  add('Türk Dili ve Edebiyatı','Şiir','Şiirde anlam; sözcüklerin sözlük değerinden çok imge, çağrışım, ses ve yapı ilişkisiyle kurulur. Nazım birimi, ölçü, uyak ve redif biçim özelliklerini; tema ve şiir anlayışı içerik yönünü gösterir. Cumhuriyet dönemi şiirinde saf şiir estetik yoğunluğa, toplumcu şiir toplumsal gerçekliğe, Garip gündelik söyleyişe, İkinci Yeni ise yoğun ve alışılmadık imgelere yönelebilir. Bir şiiri topluluğa yerleştirirken dil, imge, biçim ve dünya görüşünden en az iki kanıt aranmalıdır.',['İmge|Sözcüklerin yeni çağrışım ilişkileriyle kurduğu zihinsel tasarımdır.','Ahenk|Ölçü, uyak, tekrar ve ses düzeniyle oluşur.','Tema|Şiirin çevresinde kurulduğu temel duygu veya düşüncedir.','Şiir anlayışı|Biçim, dil ve sanat amacı konusundaki ortak yönelimdir.'],'Gündelik konuşma dili, sıradan insan ve ölçü-uyak zorunluluğuna tepki taşıyan bir şiirin eğilimini belirle.',['Dil ve kişi seçimi gündelik yaşamı işaret eder.','Geleneksel biçim zorunluluğuna tepki ikinci kanıttır.','Bu iki özellik Garip hareketiyle uyumludur; yalnız serbest ölçü kullanılması tek başına yeterli değildir.'],'Şair-eser ezberinden hareketle parçadaki aykırı kanıtları görmezden gelmek, dönem sorularında yanlış eşleştirmeye yol açar.',{type:'timeline',title:'Cumhuriyet şiirinde seçili yönelimler',items:['Saf şiir','Toplumcu şiir','Garip','İkinci Yeni']});
  add('Türk Dili ve Edebiyatı','Roman','Roman, geniş zaman ve kişi kadrosuyla bireyi ve toplumu kurmaca bir evrende işler. Anlatıcı birinci ya da üçüncü kişi olabilir; bakış açısı ise anlatıcının neyi bilip görebildiğini belirler. İç çözümleme anlatıcının karakteri açıklaması, iç monolog karakterin düşüncesini doğrudan aktarması, bilinç akışı çağrışımlı zihinsel süreci vermesidir. Modernist romanda zaman parçalanabilir, olay ikinci plana çekilebilir ve okurdan boşlukları tamamlaması beklenebilir.',['Bakış açısı|Hâkim, gözlemci ve kahraman bakış açıları bilgi sınırıyla ayrılır.','Zaman|Öykü zamanı ile anlatma zamanı farklı düzenlenebilir.','Gösterme|Diyalog ve sahne yoluyla okurun doğrudan gözlemlemesine alan açar.','Geriye dönüş|Şimdiki akışı geçmişteki bir olaya bağlayan tekniktir.'],'Bir romanda anlatıcı bütün kişilerin düşüncelerini biliyor ve gelecekte olacakları sezdiriyorsa bakış açısını belirle.',['Anlatıcının birden fazla kişinin iç dünyasına eriştiği görülür.','Zaman ve bilgi sınırının karakterlerden geniş olduğu saptanır.','Bu göstergeler hâkim/ilahi bakış açısını destekler.'],'Birinci kişi anlatımı her zaman yazarın hayatı sanmak yanlıştır; konuşan ses kurmaca bir anlatıcı olabilir.',{type:'flow',title:'Roman çözümleme sırası',items:['Anlatıcı kim?','Ne kadar biliyor?','Zaman nasıl?','Teknik ne sağlıyor?']});
  add('Türk Dili ve Edebiyatı','Tiyatro','Tiyatro metni sahnelenmek üzere kurulur; olay örgüsü diyalog, çatışma, sahne yönergesi, dekor ve oyuncu hareketiyle görünür hâle gelir. Trajedi, komedi ve dram tarihsel türlerdir; modern eserler bu sınırları birleştirebilir. Geleneksel Türk tiyatrosunda doğaçlama, tipler ve sözlü yapı belirginken modern tiyatro yazılı metin, perde-sahne düzeni ve dramatik yapıdan yararlanır. Soru çözümünde konuşma metni ile sahne yönergesi birbirinden ayrılmalıdır.',['Çatışma|Karşıt istek, değer veya güçlerin dramatik gerilimidir.','Sahne yönergesi|Oyuncu, dekor, ışık ya da hareket için metin içi açıklamadır.','Tip|Belirli toplumsal özelliği öne çıkaran, genelleştirilmiş kişidir.','Dramatik ironi|Seyircinin bildiğini kişinin bilmemesinden doğan etkidir.'],'Parantez içinde “Kapıya yönelir, ışık azalır” ifadesi bulunan bir metinde bu bölümün işlevini açıkla.',['İfade karakterlerin konuşmasının parçası değildir.','Hareket ve ışık düzenini sahne ekibine bildirir.','Bu nedenle sahne yönergesidir ve atmosfer ile eylemin görünür kurulmasına hizmet eder.'],'Her karşılıklı konuşmayı tiyatro saymak yanlıştır; dramatik metinde sahneleme düzeni ve çatışma örgüsü de aranır.',{type:'compare',title:'Tiyatroda iki metin katmanı',items:['Diyalog: kişilerin sözü','Yönerge: sahne eylemi','Çatışma: yapının motoru']});
  add('Türk Dili ve Edebiyatı','Deneme ve Eleştiri','Deneme, yazarın bir konu çevresindeki kişisel düşüncesini serbest, konuşma havasında ve kesin kanıtlama zorunluluğu olmadan işler. Eleştiri ise bir eseri, yazarı veya sanat anlayışını belirli ölçütler üzerinden değerlendirir; öznel ya da nesnel eğilim gösterebilir. Makale kanıtlama ve bilgi verme amacıyla daha sistematik ilerler. Tür belirlerken birinci kişi kullanımı tek başına yeterli değildir; amaç, savın kuruluşu, kanıt ve değerlendirme ölçütleri birlikte incelenir.',['Deneme|Kişisel düşünce ve serbest çağrışım ağırlıklıdır.','Eleştiri|Değerlendirme nesnesi ve ölçütü bulunur.','Makale|Savı bilgi ve kanıtla temellendirmeyi amaçlar.','Üslup|Yazarın dili kullanma ve anlatma biçimidir.'],'Bir yazarın romanı karakter tutarlılığı, dil ve kurgu ölçütleriyle değerlendirilen metnin türünü belirle.',['Metnin belirli bir eseri değerlendirdiği saptanır.','Karakter, dil ve kurgu açık ölçütlerdir.','Bu yapı eleştiri türünü gösterir; değerlendirmede kişisel yargı bulunması türü denemeye dönüştürmez.'],'“Bence” sözcüğünü gördüğünde doğrudan deneme seçmek güvenilir değildir; eleştiri de öznel yargı taşıyabilir.',{type:'flow',title:'Düşünce yazısını ayırma',items:['Amaç','Kanıt düzeni','Ölçüt','Yazar tutumu']});
  add('Türk Dili ve Edebiyatı','Söylev ve Mülakat','Söylev, bir topluluğu belirli düşünce ya da eylem yönünde etkilemek için seslenme, vurgu, tekrar ve retorik sorulardan yararlanır. Mülakat, alanında tanınan bir kişiden soru-cevap yoluyla bilgi ve görüş edinir; gazeteci sorularını hazırlarken konuyu ve kişiyi araştırır. Röportajda gözlem, betimleme, belge ve farklı kişilerden alınan görüşler daha geniş bir çevre oluşturabilir. Tür ayrımında konuşmacı-dinleyici ilişkisi ile metnin kuruluş biçimi belirleyicidir.',['Hitabet|Topluluk önünde etkili ve amaçlı konuşma sanatıdır.','Retorik soru|Cevap beklemekten çok etki ve vurgu kurar.','Mülakat|Sorular belirli bir kişiye ve amaca göre hazırlanır.','Röportaj|Yerinde gözlem ve betimleme mülakattan daha belirgin olabilir.'],'“Değerli arkadaşlar, bugün burada geleceğimizi birlikte kurmak için toplandık” diye başlayan metnin baskın türünü ve iki göstergesini belirt.',['Doğrudan topluluğa seslenme “değerli arkadaşlar” ifadesinde görülür.','Birlikte eyleme yöneltme ve ikna amacı vardır.','Bu göstergeler söylev türünü destekler; soru-cevap düzeni olmadığı için mülakat değildir.'],'Metinde bir kişinin sözlerinin bulunmasını mülakat için yeterli saymak yanlıştır; planlı soru-cevap yapısı aranmalıdır.',{type:'compare',title:'Sözlü anlatım türleri',items:['Söylev: topluluğu etkileme','Mülakat: kişiden bilgi alma','Röportaj: gözlemle genişletme']});
  add('Fizik','Çembersel Hareket','Düzgün çembersel harekette süratin büyüklüğü sabit olabilir; fakat hız vektörünün yönü sürekli değiştiği için ivme vardır. Merkezcil ivme çemberin merkezine yönelir ve a_m=v²/r=ω²r bağıntısıyla bulunur. “Merkezcil kuvvet” ayrı bir etkileşim değildir; ağırlık, gerilme, sürtünme veya normal kuvvetlerin merkeze doğru bileşkesinin adıdır. Serbest cisim diyagramında önce gerçek kuvvetler çizilir, sonra radyal yöndeki net kuvvet m·v²/r’ye eşitlenir.',['Açısal hız|ω=2π/T=2πf.','Doğrusal hız|v=ωr.','Merkezcil ivme|a_m=v²/r ve merkeze yönelir.','Net radyal kuvvet|ΣF_r=m·v²/r.'],'0,5 kg kütleli bir cisim 2 m yarıçaplı çemberde 4 m/s süratle dönüyor. Merkeze doğru net kuvveti bul.',['Merkezcil ivme a_m=v²/r=16/2=8 m/s² bulunur.','Net radyal kuvvet F=m·a=0,5·8 olarak yazılır.','Sonuç 4 N’dir ve yönü merkezedir.'],'Diyagrama ayrıca “merkezcil kuvvet” eklemek, aynı net etkiyi iki kez saymaktır; yalnız gerçek etkileşim kuvvetleri çizilir.',{type:'flow',title:'Çembersel harekette yönler',items:['Hız: teğet','İvme: merkez','Net kuvvet: merkez']});
  add('Fizik','Basit Harmonik Hareket','Basit harmonik hareket, denge noktasına doğru ve uzanımla orantılı geri çağırıcı etkinin bulunduğu ideal salınımdır. Yay için F=−kx, ivme için a=−ω²x bağıntısındaki eksi işareti yönün uzanıma zıt olduğunu gösterir. Denge noktasında potansiyel enerji en küçük ve sürat en büyük; uçlarda sürat sıfır ve geri çağırıcı ivmenin büyüklüğü en fazladır. Yay-kütle sisteminde periyot ideal koşullarda genliğe değil m ve k’ye bağlıdır.',['Uzanım|Denge konumundan yönlü uzaklık x’tir.','Periyot|Yayda T=2π√(m/k).','Enerji|Toplam mekanik enerji ideal sistemde sabittir.','Faz|Konum, hız ve ivme aynı anda maksimum olmaz.'],'k=200 N/m yayına bağlı 2 kg cismin ideal salınım periyodunu bul.',['T=2π√(m/k) bağıntısı seçilir.','m/k=2/200=0,01 s² ve karekökü 0,1 s’tir.','T=0,2π s, yaklaşık 0,63 s bulunur.'],'Uç noktada ivmenin de sıfır olduğunu sanmak yaygın hatadır; orada hız sıfır, ivme büyüklüğü maksimumdur.',{type:'timeline',title:'Bir salınım boyunca enerji değişimi',items:['Sol uç: E_p maks.','Denge: E_k maks.','Sağ uç: E_p maks.']});
  add('Fizik','Dalga Mekaniği','Dalga, enerjiyi ortamda ya da boşlukta taşıyan bir bozulmadır; ortam tanecikleri dalgayla birlikte net olarak taşınmak zorunda değildir. Periyodik dalgalarda v=fλ bağıntısı hız, frekans ve dalga boyunu bağlar. Kaynak frekansı belirler, ortam dalga hızını belirler; ortam değiştiğinde frekans sabit kalırken dalga boyu değişebilir. Girişim üst üste binme, kırınım engel veya açıklık çevresine yayılma, Doppler ise kaynak-gözlemci göreli hareketi nedeniyle algılanan frekans değişimidir.',['Dalga boyu|Aynı fazdaki ardışık iki nokta arasındaki uzaklıktır.','Girişim|Genlikler üst üste binme ilkesine göre toplanır.','Kırınım|Açıklık boyutu dalga boyuna yaklaştıkça belirginleşir.','Doppler|Göreli yaklaşmada algılanan frekans artar.'],'Frekansı 5 Hz, dalga boyu 2 m olan periyodik dalganın hızını bul.',['v=fλ bağıntısı kullanılır.','5 s⁻¹ ile 2 m çarpılır.','Dalga hızı 10 m/s bulunur.'],'Dalga ortam değiştirince frekansın da zorunlu olarak değiştiğini düşünmek yanlıştır; frekans kaynağın salınımına bağlıdır.',{type:'curve',title:'Dalganın temel büyüklükleri',items:['genlik','dalga boyu λ','yayılma yönü']});
  add('Fizik','Atom Fiziğine Giriş ve Radyoaktivite','Atomların elektron enerjileri kesikli düzeyler hâlindedir. Elektron üst düzeye enerji alarak çıkar; alt düzeye inerken düzey farkı kadar enerjili foton yayabilir ve ΔE=hf bağıntısı kullanılır. Radyoaktif bozunma kararsız çekirdeklerin kendiliğinden dönüşümüdür; tek bir çekirdeğin ne zaman bozunacağı bilinmez fakat büyük topluluk için istatistiksel yasa işler. Yarı ömür, kalan çekirdek sayısının ya da etkinliğin yarıya inme süresidir ve başlangıç miktarından bağımsızdır.',['Enerji düzeyi|Elektron her ara enerjiye değil izinli değerlere sahip olur.','Foton|Enerjisi E=hf’dir.','Yarı ömür|N=N₀(1/2)^(t/T₁/₂).','Bozunma|Alfa, beta ve gama süreçleri yük/kütle etkileriyle ayrılır.'],'Başlangıçta 80 mg radyoaktif örneğin yarı ömrü 6 saattir. 18 saat sonra ne kadar kalır?',['18/6=3 yarı ömür geçtiği belirlenir.','Miktar sırasıyla 80→40→20→10 mg olur.','Kalan miktar 10 mg’dır.'],'Yarı ömür azalmasını doğrusal kabul edip her sürede aynı miktarı çıkarmak yanlıştır; her adımda kalan miktar yarılanır.',{type:'bars',title:'Üç yarı ömürde kalan miktar',items:['80 mg','40 mg','20 mg','10 mg']});
  add('Fizik','Modern Fizik','Modern fizik, ışık ve maddenin klasik modellerle açıklanamayan davranışlarını inceler. Fotoelektrik olayda bir fotonun enerjisi hf’dir; metalden elektron kopması için eşik enerji aşılmalıdır ve maksimum kinetik enerji K_max=hf−φ olur. Işık şiddeti uygun frekansta kopan elektron sayısını etkileyebilir, fakat eşik altındaki fotonları tek başına yeterli hâle getirmez. Madde parçacıklarının de Broglie dalga boyu λ=h/p bağıntısıyla momentuma bağlanır. Özel görelilikte ışık hızı eylemsiz gözlemciler için aynıdır.',['Eşik frekans|hf₀=φ koşuluyla belirlenir.','İş fonksiyonu|Elektronu metalden ayırmak için gereken en küçük enerjidir.','de Broglie|Momentum arttıkça madde dalga boyu azalır.','Görelilik|Zaman ve uzunluk ölçümleri gözlemcinin hareketine bağlı olabilir.'],'Enerjisi 3 eV olan foton, iş fonksiyonu 2 eV olan yüzeye çarpıyor. En büyük elektron kinetik enerjisini bul.',['Foton enerjisinin eşik enerjiden büyük olduğu kontrol edilir.','K_max=E_foton−φ=3−2 yazılır.','Maksimum kinetik enerji 1 eV’dur.'],'Fotoelektrikte şiddeti artırmanın elektronların maksimum enerjisini her koşulda artırdığını sanmak yanlıştır; enerji öncelikle foton frekansına bağlıdır.',{type:'flow',title:'Fotoelektrik enerji bilançosu',items:['Foton enerjisi hf','İş fonksiyonu φ','Kalan: K maks.']});
  add('Fizik','Modern Fiziğin Teknolojideki Uygulamaları','Modern fizik; yarı iletken, lazer, görüntüleme, nanoteknoloji ve süperiletkenlik gibi alanlarda ölçülebilir uygulamalara dönüşür. Yarı iletkenlerde bant yapısı ve katkılama ile iletkenlik kontrol edilir; diyot akımı büyük ölçüde tek yönde geçirir. Lazer, uyarılmış ışıma sayesinde dar frekans aralıklı ve uyumlu ışık üretir. MR görüntüleme güçlü manyetik alan ve radyo frekansı etkileşiminden, röntgen ise iyonlaştırıcı X ışınlarının dokularda farklı soğurulmasından yararlanır. Uygulama sorusunda cihaz adından çok fiziksel mekanizma aranmalıdır.',['Yarı iletken|İletkenliği sıcaklık ve katkılama ile değiştirilebilir.','Lazer|Uyarılmış ışıma ve optik geri besleme kullanır.','MR|Güçlü manyetik alan ve radyo frekansı darbeleriyle çalışır.','Nanoteknoloji|Boyuta bağlı özelliklerin kontrollü kullanımını inceler.'],'MR ile röntgeni kullanılan fiziksel etkileşim bakımından karşılaştır.',['MR için güçlü manyetik alan ve radyo frekansı etkileşimi belirlenir.','Röntgende X ışınlarının dokulardaki farklı soğurulması kullanılır.','Bu nedenle ikisi aynı görüntüleme amacına hizmet etse de temel mekanizmaları ve iyonlaştırıcı ışınım durumları farklıdır.'],'Tüm tıbbi görüntüleme cihazlarını “radyoaktif” saymak yanlıştır; kullanılan dalga ve etkileşim türü ayrı ayrı değerlendirilir.',{type:'compare',title:'Teknoloji ve temel ilke',items:['Diyot: bant yapısı','Lazer: uyarılmış ışıma','MR: manyetik rezonans','Röntgen: X ışını soğurması']});
  add('Kimya','Kimya ve Elektrik','Elektrokimya, yükseltgenme-indirgenme tepkimelerinde elektron aktarımı ile elektrik enerjisi arasındaki ilişkiyi inceler. Yükseltgenmede elektron verilir ve yükseltgenme basamağı artar; indirgenmede elektron alınır ve basamak azalır. Anot her hücrede yükseltgenmenin, katot indirgenmenin gerçekleştiği elektrottur. Galvanik hücre istemli tepkimeden elektrik üretirken elektroliz hücresi istemsiz tepkimeyi dış enerjiyle yürütür. Standart pil potansiyeli indirgenme potansiyelleri kullanılarak E°_hücre=E°_katot−E°_anot biçiminde hesaplanır.',['Anot|Yükseltgenmenin gerçekleştiği elektrottur.','Katot|İndirgenmenin gerçekleştiği elektrottur.','Elektron akışı|Dış devrede anottan katoda doğrudur.','Tuz köprüsü|Çözeltilerde yük dengesinin sürmesine yardım eder.'],'E°(Cu²⁺/Cu)=+0,34 V ve E°(Zn²⁺/Zn)=−0,76 V ise Zn-Cu galvanik hücresinin standart potansiyelini bul.',['Daha büyük indirgenme potansiyeline sahip Cu katot, Zn anot seçilir.','E°_hücre=0,34−(−0,76) olarak yazılır.','E°_hücre=+1,10 V bulunur; pozitif değer standart koşullarda istemli hücre tepkimesiyle uyumludur.'],'“Anot negatiftir, katot pozitiftir” ifadesini her hücreye genellemek yanlıştır; adlar tepkime türüne, işaretler hücre türüne bağlıdır.',{type:'flow',title:'Galvanik hücrede elektron yolu',items:['Zn anot: e⁻ verir','Dış devre','Cu katot: e⁻ alır']});
  add('Kimya','Karbon Kimyasına Giriş','Karbon dört değerlik elektronu sayesinde zincir, halka ve çoklu bağ içeren çok sayıda yapı kurabilir. Hibritleşme, molekül geometrisini anlamak için atom orbitallerinin bağ yapmaya uygun eşdeğer orbitaller olarak modellenmesidir: sp³ çoğunlukla tetrahedral, sp² düzlemsel üçgen, sp doğrusal geometriyle ilişkilidir. Tek bağ bir sigma; çift bağ bir sigma ve bir pi; üçlü bağ bir sigma ve iki pi bağından oluşur. Aynı molekül formülüne sahip farklı bağlantılar yapı izomerliğini doğurabilir.',['sp³|Dört sigma bağ bölgesi; yaklaşık tetrahedral düzen.','sp²|Üç bağ bölgesi; bir pi bağı oluşmasına uygun düzen.','sp|İki bağ bölgesi; doğrusal düzen.','Allotrop|Aynı elementin farklı bağlanma/yapı biçimleridir.'],'Etin (C₂H₂) molekülündeki her karbonun hibritleşmesini ve C-C bağ türünü belirle.',['Her karbon iki elektron bölgesine sahiptir: bir C-H ve bir C-C doğrultusu.','İki bölge doğrusal sp hibritleşmesini gösterir.','C≡C bağı bir sigma ve iki pi bağından oluşur.'],'Molekülün düzlemde çizimini gerçek üç boyutlu geometri sanmak veya tüm karbonları otomatik olarak sp³ kabul etmek hatadır.',{type:'compare',title:'Karbon çevresindeki bağ düzeni',items:['sp³: 4 bölge','sp²: 3 bölge','sp: 2 bölge']});
  add('Kimya','Organik Bileşikler','Organik bileşikler karbon iskeleti ve fonksiyonel gruplarına göre sınıflandırılır. Alkan, alken ve alkinler yalnız karbon-hidrojen iskeleti içerirken alkol, eter, aldehit, keton, karboksilik asit, ester ve amin gibi sınıflar karakteristik gruplarla tanınır. Adlandırmada en uzun uygun ana zincir seçilir, öncelikli fonksiyonel gruba en küçük numarayı verecek yönden numaralanır ve yan gruplar belirtilir. Kaynama, çözünürlük ve tepkime davranışı; molekül kütlesi kadar polarite ve moleküller arası etkileşimlere de bağlıdır.',['Fonksiyonel grup|Bileşiğin karakteristik tepkimelerini belirleyen atom grubudur.','Homolog seri|Ardışık üyeleri çoğunlukla CH₂ farkıyla değişen bileşik ailesidir.','İzomerlik|Aynı formülün farklı bağlantı veya uzay düzeni göstermesidir.','Polarite|Çözünürlük ve kaynama davranışını etkiler.'],'CH₃CH₂OH bileşiğinin sınıfını, adını ve suda çözünmesini etkileyen temel etkileşimi belirt.',['İki karbonlu ana zincir “etan” kökünü verir.','−OH grubu alkol sınıfını ve “etanol” adını oluşturur.','−OH grubu suyla hidrojen bağı kurabildiği için küçük molekülün suyla etkileşimi güçlüdür.'],'Ana zinciri yalnız en çok karbon içerdiği için seçmek yeterli değildir; öncelikli fonksiyonel grubu içermesi gerekir.',{type:'flow',title:'Organik bileşiği tanıma',items:['Fonksiyonel grup','Ana zincir','Numaralandırma','Ad ve özellik']});
  add('Kimya','Enerji Kaynakları ve Bilimsel Gelişmeler','Enerji kaynakları yalnız “yenilenebilir-yenilenemez” etiketiyle değil; yaşam döngüsü emisyonu, süreklilik, kapasite faktörü, depolama, arazi ve su kullanımı, güvenlik ve maliyet ölçütleriyle değerlendirilir. Güneş ve rüzgâr işletmede doğrudan yakıt yakmaz fakat üretimleri değişkendir; şebeke yönetimi ve depolama gerekebilir. Fosil yakıtlar kontrol edilebilir üretim sağlar ancak yanma sonucu sera gazı ve hava kirleticileri oluşturur. Nükleer enerji düşük işletme karbonuyla yüksek enerji yoğunluğu sunarken atık ve güvenlik yönetimi gerektirir.',['Enerji yoğunluğu|Birim kütle veya hacimden elde edilen enerji miktarıdır.','Süreklilik|Kaynağın talep anında üretim sağlayabilme durumudur.','Yaşam döngüsü|Üretimden söküme kadar bütün çevresel etkileri kapsar.','Depolama|Değişken üretim ile talep arasındaki zamanı dengeleyebilir.'],'Bir okul çatısı için güneş paneli ile doğal gaz jeneratörünü dört ölçütle karşılaştır.',['Güneşte yakıt gideri ve işletme emisyonu düşüktür; üretim ışınıma bağlı ve değişkendir.','Doğal gaz istenen zamanda çalışabilir; yakıt maliyeti ve yanma emisyonu vardır.','Karar; yerel güneşlenme, depolama/şebeke erişimi, maliyet ve çevresel hedefler birlikte değerlendirilerek verilir.'],'Tek bir ölçütte üstün olan kaynağı her koşulda “en iyi” ilan etmek sistem ihtiyacını, zamanlamayı ve yaşam döngüsünü görmezden gelir.',{type:'compare',title:'Enerji kaynağı karar matrisi',items:['Emisyon','Süreklilik','Maliyet','Depolama ve şebeke']});
  add('Biyoloji','Genden Proteine','Kalıtsal bilgi DNA’nın nükleotit dizisinde taşınır. Replikasyonda DNA kendini yarı korunumlu biçimde eşler; her yeni molekül bir eski, bir yeni zincir içerir. Transkripsiyonda bir DNA kalıbından RNA sentezlenir. Ökaryotlarda işlenen mRNA ribozoma ulaşır; translasyonda tRNA’ların taşıdığı amino asitler kodon sırasına göre polipeptide bağlanır. Genetik kod büyük ölçüde evrensel, üçlü ve birden fazla kodonun aynı amino asidi gösterebildiği bir yapıdır. Mutasyonun etkisi konum ve türüne göre değişir.',['Replikasyon|DNA→DNA bilgi aktarımıdır.','Transkripsiyon|DNA kalıbından RNA sentezidir.','Kodon|mRNA üzerindeki üç nükleotitlik anlam birimidir.','Translasyon|Ribozomda mRNA bilgisinin amino asit dizisine çevrilmesidir.'],'5′-AUG-GCU-UAA-3′ mRNA dizisinin translasyon ürününü başlangıç ve dur kodonlarını dikkate alarak belirle.',['AUG başlangıç kodonudur ve metiyonini kodlar.','GCU alanini kodlar.','UAA dur kodonudur, amino asit eklemez; ürün Metiyonin–Alanin dizisidir.'],'Dur kodonunu bir amino asit gibi zincire eklemek veya DNA, RNA ve protein sentezlerinin hücredeki yerlerini karıştırmak sık hatadır.',{type:'flow',title:'Kalıtsal bilginin ürüne dönüşmesi',items:['DNA','mRNA','Ribozom','Polipeptit']});
  add('Biyoloji','Canlılarda Enerji Dönüşümleri','Canlılar enerjiyi yoktan üretmez; ışık veya kimyasal bağ enerjisini hücresel işte kullanılabilir biçimlere dönüştürür. Fotosentezin ışığa bağlı tepkimelerinde ATP ve indirgen güç oluşur, karbon bağlama tepkimelerinde CO₂ organik molekül yapısına katılır. Hücresel solunumda glikoliz, sitrik asit döngüsü ve elektron taşıma sistemi boyunca organik moleküllerin enerjisi basamaklı olarak aktarılır. Oksijenli solunumda oksijen son elektron alıcısıdır. ATP kısa süreli enerji aktarım aracıdır; uzun süreli depo değildir.',['Fotosentez|Işık enerjisini kimyasal bağ enerjisine dönüştürür.','Glikoliz|Sitoplazmada glikozun parçalanmasının ilk basamağıdır.','Elektron taşıma|Proton gradyanı üzerinden ATP sentezini destekler.','ATP|Fosfat aktarımıyla hücresel işlere enerji bağlar.'],'Oksijen bir hücreden çekildiğinde glikoliz ile elektron taşıma sisteminin etkilenmesini karşılaştır.',['Glikoliz oksijeni doğrudan kullanmadığı için uygun NAD⁺ yenilenmesi varsa bir süre sürebilir.','Oksijenli solunumun elektron taşıma zincirinde son elektron alıcısı bulunamaz.','Elektron taşıma ve oksidatif fosforilasyon büyük ölçüde durur; ATP verimi belirgin azalır.'],'“Bitkiler yalnız fotosentez yapar, solunum yapmaz” yanlıştır; bitki hücreleri de organik maddeden ATP elde etmek için solunum yapar.',{type:'cycle',title:'Enerji ve madde ilişkisi',items:['Işık','Organik molekül','Hücresel solunum','ATP ve ısı']});
  add('Biyoloji','Bitki Biyolojisi','Bitkilerde kök, gövde ve yaprak; örtü, temel ve iletim dokularının iş birliğiyle çalışır. Ksilem su ve mineralleri büyük ölçüde kökten yapraklara taşır; terleme, kohezyon ve gerilim bu harekete katkı sağlar. Floem, kaynak dokularda üretilen veya depodan çıkarılan organik maddeleri tüketen hedef dokulara taşır; yön, kaynak-hedef ilişkisine göre değişebilir. Stomalar gaz alışverişi ve su kaybını düzenler. Oksin, giberellin, sitokinin, etilen ve absisik asit gibi hormonlar büyüme ve çevresel yanıtları koordine eder.',['Ksilem|Su ve mineral taşınmasında görev alan çoğunlukla ölü iletim elemanları içerir.','Floem|Organik maddeyi kaynak ile hedef arasında taşır.','Stoma|CO₂ alımı ile su kaybı arasında düzenleme sağlar.','Tropizma|Uyaran yönüne bağlı büyüme yanıtıdır.'],'Bir ağacın gövdesinde floem halkası zarar görürken ksilem büyük ölçüde sağlam kalırsa ilk olarak hangi taşımalar etkilenir?',['Floemin yaprakta üretilen şekerleri kök ve büyüyen dokulara taşıdığı hatırlanır.','Floem hasarı organik besin taşınmasını kesintiye uğratır.','Ksilem sağlam olduğundan su-mineral taşınması başlangıçta sürebilir; uzun vadede köklerin beslenememesi tüm bitkiyi etkiler.'],'Ksilemi yalnız aşağıdan yukarı, floemi yalnız yukarıdan aşağı ezberiyle açıklamak yetersizdir; floemde yön kaynak ve hedefe bağlıdır.',{type:'flow',title:'Bitkide iki iletim yolu',items:['Kök','Ksilem→Yaprak','Kaynak→Floem→Hedef']});
  add('Biyoloji','Canlılar ve Çevre','Ekoloji; birey, popülasyon, komünite ve ekosistem düzeylerinde canlıların birbirleri ve çevreleriyle ilişkisini inceler. Popülasyon büyüklüğü doğum, ölüm, göç ve kaynaklarla değişir; taşıma kapasitesi ortamın uzun süre destekleyebileceği yaklaşık üst sınırdır. Besin zincirinde enerji tek yönlü akar ve her trofik aktarımda kullanılabilir miktar azalır; madde ise su, karbon ve azot döngüleriyle yeniden kullanılır. Rekabet, av-avcı, mutualizm ve parazitlik komünite yapısını etkiler. İnsan etkinlikleri habitat, iklim ve biyoçeşitlilik üzerinde çoklu baskılar oluşturabilir.',['Popülasyon|Aynı türün belirli alan ve zamanda yaşayan bireyleridir.','Komünite|Bir alandaki farklı tür popülasyonlarının bütünüdür.','Taşıma kapasitesi|Kaynakların sürdürebildiği yaklaşık popülasyon düzeyidir.','Biyobirikim|Bir maddenin organizmada zamanla birikmesidir.'],'Üreticilerde 20.000 kJ kullanılabilir enerji bulunan basit bir piramitte üst basamaklarda neden daha az enerji beklenir?',['Canlıların aldığı enerjinin bir kısmı solunum ve yaşamsal faaliyetlerde kullanılıp ısı olarak dağılır.','Biyokütlenin tamamı yenmez veya sindirilmez.','Bu nedenle her aktarımda üst trofik düzeye geçen kullanılabilir enerji azalır; sabit bir yüzde her sistem için zorunlu değildir.'],'Enerji ile maddenin ekosistemde aynı biçimde döndüğünü söylemek yanlıştır; enerji akarken madde döngülere katılır.',{type:'bars',title:'Trofik düzeylerde kullanılabilir enerji',items:['Üreticiler','Birincil tüketiciler','İkincil tüketiciler','Üst tüketiciler']});
  add('T.C. İnkılap Tarihi ve Atatürkçülük','20. Yüzyıl Başlarında Osmanlı Devleti','Osmanlı Devleti 20. yüzyıl başında siyasi merkezileşme arayışı, milliyetçilik hareketleri, dış borçlar ve büyük devlet rekabetiyle karşı karşıyaydı. Trablusgarp Savaşı’nda İtalya’nın saldırısı Kuzey Afrika’daki son Osmanlı toprağının kaybına giden süreci başlattı. Balkan Savaşları Rumeli’de büyük toprak ve nüfus kaybı yarattı. I. Dünya Savaşı’nda farklı cephelerde mücadele eden devlet, Mondros Ateşkes Antlaşması sonrasında işgallere açık hâle geldi. Millî Mücadele ortamı bu uzun neden-sonuç zincirinin içinde değerlendirilmelidir.',['Trablusgarp|İtalya ile savaş, Uşi Antlaşması ve Kuzey Afrika’daki egemenliğin sona ermesi süreci.','Balkan Savaşları|Rumeli topraklarının büyük bölümünün kaybı ve kitlesel göçler.','I. Dünya Savaşı|İttifak sistemi içinde çok cepheli mücadele.','Mondros|Ateşkes hükümleri işgallerin dayanağı olarak kullanıldı.'],'Trablusgarp Savaşı, Balkan Savaşları, I. Dünya Savaşı ve Mondros’u kronolojik ve nedensel sıraya yerleştir.',['Trablusgarp Savaşı 1911-1912 ile başlanır.','Balkan Savaşları 1912-1913, ardından 1914-1918 I. Dünya Savaşı gelir.','30 Ekim 1918 Mondros Ateşkesi savaş sonrasındaki işgal ortamına geçişi gösterir.'],'Mondros’u bir barış antlaşması sanmak yanlıştır; ateşkestir ve kesin barış düzeninden farklıdır.',{type:'timeline',title:'Millî Mücadele öncesi kırılmalar',items:['1911 Trablusgarp','1912-13 Balkan Savaşları','1914-18 I. Dünya Savaşı','1918 Mondros']});
  add('T.C. İnkılap Tarihi ve Atatürkçülük','Millî Mücadele’nin Hazırlık Dönemi','Hazırlık döneminde dağınık yerel direnişler ortak amaç ve temsil çevresinde birleştirildi. Amasya Genelgesi bağımsızlığın milletin azim ve kararıyla kurtarılacağı düşüncesini açıklayıp ulusal kongre çağrısı yaptı. Erzurum Kongresi bölgesel toplanmasına rağmen vatanın bütünlüğü gibi ulusal kararlar aldı. Sivas Kongresi ulusal nitelikteydi ve direniş örgütlerinin birleştirilmesini güçlendirdi. Temsil Heyeti yürütme benzeri işlev üstlendi; Misak-ı Millî ve İstanbul’un işgali süreci TBMM’nin açılmasına zemin hazırladı.',['Amasya Genelgesi|Gerekçe, amaç ve yöntem vurgusuyla ulusal egemenlik fikrini öne çıkardı.','Erzurum Kongresi|Toplanışı bölgesel, kararlarının önemli bölümü ulusaldır.','Sivas Kongresi|Ulusal kongre ve örgütsel birleşme adımıdır.','TBMM|23 Nisan 1920’de millî iradenin kurumsal merkezi oldu.'],'“Milletin bağımsızlığını yine milletin azim ve kararı kurtaracaktır” ifadesinin yönetim anlayışı bakımından önemini açıkla.',['Kurtuluşun kaynağı padişah veya dış yardım değil millet olarak gösterilir.','Karar verme yetkisi millî iradeye bağlanır.','İfade, ulusal egemenliğe dayalı yeni siyasi düzenin düşünsel işaretlerinden biridir.'],'Erzurum Kongresi’ni yalnız bölgesel saymak kararlarının ulusal boyutunu; Sivas’ı yalnız karar tekrarı saymak örgütsel rolünü gözden kaçırır.',{type:'timeline',title:'Ulusal örgütlenme basamakları',items:['Amasya','Erzurum','Sivas','Temsil Heyeti','TBMM']});
  add('T.C. İnkılap Tarihi ve Atatürkçülük','Kurtuluş Savaşı Cepheleri','Doğu Cephesi’nde düzenli birliklerin başarısı Gümrü Antlaşması’na uzandı. Güney Cephesi’nde yerel direniş, halkın ve bölgesel güçlerin etkisiyle öne çıktı; Fransa ile Ankara Antlaşması çatışmanın büyük ölçüde sona ermesinde etkili oldu. Batı Cephesi, düzenli ordunun Yunan kuvvetlerine karşı İnönü savaşları, Sakarya Meydan Muharebesi ve Büyük Taarruz çizgisinde ana askerî alan oldu. Askerî başarılar diplomatik sonuç doğurdu; Mudanya Ateşkesi silahlı çatışmayı durdurup Lozan görüşmelerinin yolunu açtı.',['Doğu Cephesi|Gümrü Antlaşması’yla ilişkilendirilir.','Güney Cephesi|Yerel direniş ve Fransa ile Ankara Antlaşması öne çıkar.','Batı Cephesi|Düzenli ordunun ana cephesi ve kesin askerî sonucun alanıdır.','Mudanya|Ateşkes yoluyla savaş safhasından diplomasiye geçiştir.'],'Sakarya, Büyük Taarruz ve Mudanya arasındaki askerî-diplomatik ilişkiyi kur.',['Sakarya savunma başarısı stratejik inisiyatifi güçlendirdi.','Büyük Taarruz Yunan ana kuvvetlerinin Anadolu’dan çıkarılmasını sağladı.','Mudanya Ateşkesi çatışmayı durdurdu ve kesin barış için Lozan sürecine geçiş yarattı.'],'Her antlaşmayı “barış” olarak adlandırmak veya cepheyi yalnız komutan adıyla ezberlemek, işlev ve sonuç ayrımını bozar.',{type:'flow',title:'Askerî başarıdan diplomasiye',items:['Sakarya','Büyük Taarruz','Mudanya Ateşkesi','Lozan görüşmeleri']});
  add('T.C. İnkılap Tarihi ve Atatürkçülük','Atatürk İlke ve İnkılapları','Cumhuriyetçilik egemenliğin millete ait olmasını; milliyetçilik ortak tarih ve kültür çevresinde ulusal birliği; halkçılık hukuk önünde eşitlik ve ayrıcalıksız toplumu vurgular. Devletçilik, özel girişimi dışlamadan ekonomik kalkınmada devletin düzenleyici ve yatırımcı rolünü kabul eder. Laiklik devlet ve hukuk düzeninin din kurallarından bağımsızlaşmasını, inanç özgürlüğünün güvenceye alınmasını destekler. İnkılapçılık, çağdaşlaşma yönündeki değişimi sürdürme anlayışıdır. Bir düzenleme birden fazla ilkeyle bağ kurulabilse de sorudaki amaç baskındır.',['Cumhuriyetçilik|Millî egemenlik ve temsil.','Halkçılık|Eşit yurttaşlık ve ayrıcalıkların reddi.','Laiklik|Hukuk ve yönetimde dünyevi düzen; inanç özgürlüğü.','Devletçilik|Kalkınmada kamu-özel dengesine dayalı ekonomik rol.'],'Türk Medeni Kanunu’nun aile ve miras ilişkilerini laik hukukta düzenlemesini hangi ilkelerle ilişkilendirirsin?',['Dini hukuk yerine sivil hukuk düzeni kurulması laiklikle ilişkilidir.','Kadın ve erkek yurttaşların hukuki konumunun geliştirilmesi halkçılığın eşitlik yönüyle bağ kurar.','Sorunun vurgusuna göre baskın ilke seçilir; tek inkılaba yalnız tek ilke zorunluluğu yoktur.'],'Devletçiliği bütün özel mülkiyeti reddeden bir sistem sanmak ya da laikliği inanç karşıtlığıyla eşitlemek kavram hatasıdır.',{type:'compare',title:'İlke ve temel odak',items:['Cumhuriyetçilik: egemenlik','Halkçılık: eşitlik','Laiklik: hukuk düzeni','Devletçilik: kalkınma']});
  add('T.C. İnkılap Tarihi ve Atatürkçülük','Atatürk Dönemi İç Politika','Yeni devletin iç politikasında millî egemenliğe dayalı kurumların kurulması, hukuk ve eğitim birliğinin sağlanması ve siyasal katılımın geliştirilmesi amaçlandı. Cumhuriyet’in ilanı devlet başkanlığı ve hükûmet kurma sorununa çözüm getirdi. Çok partili hayata geçiş için Terakkiperver Cumhuriyet Fırkası ve Serbest Cumhuriyet Fırkası deneyimleri yaşandı; dönemin güvenlik ve siyasal koşulları nedeniyle kalıcı olmadılar. Ekonomik ve toplumsal düzenlemeler, yeni yurttaşlık anlayışını ve merkezi devlet kapasitesini güçlendirdi. Olaylar kendi dönem koşulları içinde değerlendirilmelidir.',['Cumhuriyet’in ilanı|Yönetim biçimini açıklaştırdı ve hükûmet sistemini düzenledi.','Çok partili denemeler|Siyasal rekabet arayışını gösterdi.','Hukuk birliği|Farklı hukuk alanlarının ortak yurttaşlık temelinde düzenlenmesi.','Eğitim birliği|Öğretim kurumlarının ortak devlet sistemi içinde toplanması.'],'Terakkiperver Cumhuriyet Fırkası ile Serbest Cumhuriyet Fırkasını amaç ve zaman bakımından ayır.',['Terakkiperver Cumhuriyet Fırkası 1924’te, ilk muhalefet partisi deneyimi olarak kuruldu.','Serbest Cumhuriyet Fırkası 1930’da farklı bir çok partili hayat denemesiydi.','İkisi aynı girişim değildir; ortak yönleri Cumhuriyet dönemindeki siyasal çoğulculuk arayışlarıdır.'],'Parti adlarını ve kuruluş yıllarını birbirine karıştırmak, olayların Takrir-i Sükûn ve 1930 koşullarıyla bağını koparır.',{type:'timeline',title:'Seçili iç politika adımları',items:['1923 Cumhuriyet','1924 TCF','1925 Takrir-i Sükûn dönemi','1930 SCF']});
  add('T.C. İnkılap Tarihi ve Atatürkçülük','Atatürk Dönemi Dış Politika','Dış politikada bağımsızlık, egemen eşitlik ve barışçı çözüm arayışı temel oldu. Lozan sonrasında nüfus mübadelesi, Musul ve yabancı okullar gibi sorunlar görüşmelerle ele alındı. Türkiye 1932’de Milletler Cemiyeti’ne katıldı; 1934 Balkan Antantı bölgesel güvenlik arayışının örneğiydi. Montrö Boğazlar Sözleşmesi 1936’da Boğazlar üzerindeki Türk egemenliğini güçlendirdi. Hatay süreci diplomasi ve halk iradesi basamaklarıyla ilerleyerek 1939’da Türkiye’ye katılmayla sonuçlandı.',['Musul|Lozan sonrasında Türkiye ile Birleşik Krallık arasında çözülen sınır sorunuydu.','Milletler Cemiyeti|Türkiye 1932’de davet üzerine katıldı.','Montrö|Boğazlar rejiminde Türkiye’nin egemenlik ve güvenlik yetkilerini güçlendirdi.','Hatay|Diplomatik süreç sonunda 1939’da Türkiye’ye katıldı.'],'Milletler Cemiyeti’ne katılım, Montrö ve Hatay gelişmelerini kronolojik sıraya koy.',['Milletler Cemiyeti üyeliği 1932’dir.','Montrö Boğazlar Sözleşmesi 1936’da imzalanmıştır.','Hatay’ın Türkiye’ye katılması 1939’dur.'],'Montrö’yü Boğazlar sorununu ilk kez ortaya çıkaran metin sanmak yanlıştır; Lozan’daki rejimi Türkiye lehine yeniden düzenlemiştir.',{type:'timeline',title:'Barışçı dış politika kazanımları',items:['1932 Milletler Cemiyeti','1934 Balkan Antantı','1936 Montrö','1939 Hatay']});
  add('T.C. İnkılap Tarihi ve Atatürkçülük','II. Dünya Savaşı ve Türkiye','II. Dünya Savaşı Mihver ve Müttefik blokları arasında Avrupa’dan küresel ölçekte yayıldı; savaş, kitlesel yıkım ve soykırımın yanında Birleşmiş Milletler düzeninin kurulmasına yol açtı. Türkiye savaş boyunca toprak bütünlüğünü korumaya ve çatışma dışında kalmaya yönelik denge politikası izledi; farklı aşamalarda diplomatik ve ekonomik baskılarla karşılaştı. Savaşın son döneminde Almanya ile ilişkiler kesildi ve 1945’te savaş ilan edildi; Türkiye fiilen büyük bir cephe savaşı yürütmedi. İçeride seferberlik koşulları, kıtlık ve ekonomik tedbirler toplumu etkiledi.',['Mihver|Başta Almanya, İtalya ve Japonya çevresindeki blok.','Müttefikler|Birleşik Krallık, SSCB, ABD ve diğer ortaklar.','Denge politikası|Savaşa doğrudan girmeden güvenliği koruma arayışı.','1945|Savaş ilanı, savaş sonrası uluslararası düzene katılım bağlamındadır.'],'Türkiye’nin 1945’te savaş ilan etmesini “savaş boyunca cephede savaşmıştır” yargısından ayır.',['Savaş yıllarında temel politika çatışma dışında kalma ve dengeydi.','Şubat 1945’te savaş ilanı savaşın son aşamasında ve yeni uluslararası düzene katılım bağlamında gerçekleşti.','İlan, Türk ordusunun uzun süreli bir Avrupa cephesinde savaş yürüttüğü anlamına gelmez.'],'Tarafsızlık politikasını savaş boyunca hiç değişmeyen ve hiçbir baskı içermeyen tek çizgi olarak görmek dönemin diplomatik aşamalarını siler.',{type:'timeline',title:'Türkiye’nin savaş yılları çizgisi',items:['Denge ve hazırlık','Müttefik baskıları','1944 Almanya ile ilişkilerin kesilmesi','1945 savaş ilanı']});
  add('T.C. İnkılap Tarihi ve Atatürkçülük','Soğuk Savaş’tan Küreselleşmeye','II. Dünya Savaşı sonrasında ABD ve SSCB çevresinde iki kutuplu sistem oluştu. Truman Doktrini ve Marshall Planı Batı blokunun güvenlik ve ekonomik yapılanmasında etkili oldu; NATO 1949’da, Varşova Paktı 1955’te kuruldu. Türkiye Kore Savaşı’na birlik gönderdi ve 1952’de NATO’ya katıldı. Soğuk Savaş yalnız askerî rekabet değil; ideoloji, teknoloji, propaganda ve vekâlet savaşlarıyla da yürüdü. SSCB’nin dağılmasıyla iki kutupluluk sona ererken küreselleşme, bölgesel çatışmalar ve yeni ekonomik ağlar öne çıktı.',['İki kutupluluk|ABD ve SSCB merkezli rakip bloklar düzeni.','NATO|1949’da kurulan kolektif savunma ittifakı.','Varşova Paktı|1955’te Sovyet bloku içinde kurulan askerî ittifak.','Küreselleşme|Ekonomi, iletişim ve siyasette sınır aşan bağların yoğunlaşması.'],'NATO’nun kuruluşu, Türkiye’nin üyeliği ve Varşova Paktı’nı kronolojik sıraya koy.',['NATO 1949’da kuruldu.','Türkiye 1952’de NATO’ya katıldı.','Varşova Paktı 1955’te kuruldu; bu sıra blokların genişleme dinamiğini gösterir.'],'NATO ile Varşova Paktı’nı aynı yıl kurulmuş saymak veya Soğuk Savaş’ı doğrudan ABD-SSCB sıcak savaşı olarak tanımlamak yanlıştır.',{type:'timeline',title:'Soğuk Savaş bloklaşması',items:['1949 NATO','1952 Türkiye NATO’da','1955 Varşova Paktı','1991 SSCB’nin dağılması']});
  add('Coğrafya','Doğal Sistemler ve Ekstrem Olaylar','Doğal sistemler atmosfer, hidrosfer, litosfer ve biyosfer arasındaki madde ve enerji alışverişiyle işler. Ekstrem olay, belirli yer ve dönem için olağanın dışında kalan şiddet veya sıklıktaki süreçtir. Tehlike zarar verme potansiyeli; maruziyet insan ve varlıkların tehlike alanında bulunması; kırılganlık etkilenme düzeyi; risk ise bunların birlikte oluşturduğu olası kayıptır. Bu nedenle aynı büyüklükteki deprem veya taşkın farklı yerlerde farklı afete dönüşebilir. Afet yönetimi zarar azaltma, hazırlık, müdahale ve iyileştirme aşamalarını kapsar.',['Tehlike|Zarar üretme potansiyeli taşıyan doğal veya beşerî süreç.','Maruziyet|Nüfus ve varlıkların tehlike alanında bulunması.','Kırılganlık|Bir toplumun etkilenmeye açıklığı.','Risk|Tehlike, maruziyet ve kırılganlığın bileşik sonucudur.'],'Aynı büyüklükte deprem yaşayan iki kentten yapı denetimi güçlü olanın neden daha az kayıp verebileceğini açıkla.',['Deprem tehlikesi benzer kabul edilir.','Dayanıklı yapı ve hazırlık kırılganlığı azaltır.','Kırılganlık azaldığı için maruziyet benzer olsa bile afet riski ve beklenen kayıp düşer.'],'“Doğal olay varsa mutlaka afet vardır” demek yanlıştır; afet, olayın insan ve sistemler üzerinde ciddi kayıp oluşturmasıyla ortaya çıkar.',{type:'flow',title:'Afet riskinin bileşenleri',items:['Tehlike','Maruziyet','Kırılganlık','Olası kayıp']});
  add('Coğrafya','Beşerî Sistemler ve Ekonomi','Nüfusun dağılışı iklim, su, yer şekli ve toprak gibi doğal; iş, ulaşım, güvenlik ve hizmet gibi beşerî etkenlerle şekillenir. Göç, çıkış ve varış yerinde yaş yapısını, iş gücünü ve kent hizmetlerini değiştirir. Ekonomik faaliyetler birincil, ikincil, üçüncül ve bilgi yoğun sektörler arasında bağlantı kurar; ham maddenin işlenmesi katma değeri artırabilir. Ulaşım ağları maliyeti ve erişilebilirliği, ticaret ise üretim-tüketim bölgeleri arasındaki bağı belirler. Harita yorumunda tek nedenli açıklamadan kaçınılmalıdır.',['Nüfus yoğunluğu|Nüfusun alana oranıdır; dağılışı tek başına açıklamaz.','Göç|İtici ve çekici nedenlerle nüfusun yer değiştirmesidir.','Katma değer|Üretim sürecinde ürüne eklenen ekonomik değerdir.','Erişilebilirlik|Bir yere ulaşma kolaylığı ve maliyetiyle ilgilidir.'],'Büyük bir liman çevresinde sanayi ve hizmetlerin yoğunlaşmasını dört coğrafi ilişkiyle açıkla.',['Deniz ulaşımı ham madde ve ürün taşıma maliyetini azaltabilir.','Kara ve demir yolu bağlantıları limanın hinterlandını genişletir.','İş olanakları göç ve nüfus artışı çekebilir.','Artan nüfus finans, lojistik ve ticaret gibi hizmetleri büyütür.'],'Bir sanayi merkezinin yerini yalnız ham maddeyle açıklamak enerji, pazar, iş gücü, sermaye ve ulaşımı gözden kaçırır.',{type:'flow',title:'Liman çevresinde ekonomik kümelenme',items:['Ulaşım','Sanayi','İstihdam','Nüfus','Hizmetler']});
  add('Coğrafya','Bölgeler ve Ülkeler','Bölge, seçilen ölçüte göre benzerlik veya işlev ilişkisi gösteren alandır; sınırları amaca göre değişebilir. Mutlak konum enlem-boylamla, göreceli konum ise ulaşım yolları, komşular, kaynaklar ve siyasi çevreyle açıklanır. Jeopolitik değerlendirme fiziksel konumun yanında ekonomi, nüfus, teknoloji ve uluslararası ilişkileri de içerir. Gelişmişlik yalnız gelirle ölçülmez; eğitim, sağlık, üretim yapısı ve yaşam koşulları birlikte ele alınır. Enerji koridorları ve bölgesel örgütler ülkeler arası bağımlılık ve iş birliğini etkiler.',['Mutlak konum|Koordinata dayalı ve değişmeyen konumdur.','Göreceli konum|Çevreyle ilişkiler ve erişim özellikleriyle tanımlanır.','Bölge|Seçilen ölçüte göre oluşturulan mekânsal bütündür.','Jeopolitik|Coğrafi ve beşerî kapasitenin güç ilişkileriyle yorumlanmasıdır.'],'İstanbul ve Çanakkale boğazlarının Türkiye’nin göreceli konumuna etkisini açıkla.',['Boğazlar Karadeniz ile Akdeniz arasındaki deniz ulaşımını bağlar.','Bu bağlantı ticaret, güvenlik ve diplomatik önem oluşturur.','Önem yalnız koordinattan değil, ulaşım ve uluslararası ilişkilerden doğduğu için göreceli konum örneğidir.'],'Göreceli konumu tamamen değişmez sanmak yanlıştır; ulaşım teknolojisi ve siyasi-ekonomik ilişkiler önemini dönüştürebilir.',{type:'compare',title:'Konum türleri',items:['Mutlak: koordinat','Göreceli: bağlantı','Jeopolitik: güç ve ilişki']});
  add('Coğrafya','Çevre ve Toplum','İnsanlar kaynaklardan yararlanırken ekosistemlerin yenilenme ve atıkları soğurma kapasitesini etkiler. Sürdürülebilirlik bugünkü gereksinimleri karşılarken gelecek kuşakların seçeneklerini daraltmamayı amaçlayan çevresel, ekonomik ve toplumsal dengedir. Döngüsel ekonomi ürün ömrünü uzatma, yeniden kullanım, onarım ve geri dönüşümle ham madde ve atık baskısını azaltır. Havza ve kıyı gibi sistemlerde bir yerdeki karar başka alanları etkilediği için mekânsal planlama bütüncül olmalıdır. Çevresel etki değerlendirmesi olası sonuçları uygulama öncesinde incelemeye yardım eder.',['Sürdürülebilirlik|Çevre, ekonomi ve toplumun uzun dönemli dengesidir.','Taşıma kapasitesi|Sistemin baskıyı sürdürebilme sınırıyla ilişkilidir.','Döngüsel ekonomi|Kaynağı kullanımda tutup atığı azaltmayı hedefler.','Havza yönetimi|Suyu idari sınırdan çok doğal akış sistemiyle ele alır.'],'Bir akarsu havzasında yeni sanayi alanı planlanırken hangi ölçütler birlikte değerlendirilmelidir?',['Su çekimi ve atık suyun miktarı ile kalitesi incelenir.','Aşağı havzadaki tarım, yerleşme ve ekosistemlerin etkilenmesi değerlendirilir.','İstihdam ve maliyet yararı; arıtma, yer seçimi, afet riski ve uzun dönemli su bütçesiyle birlikte karşılaştırılır.'],'Sadece ekonomik gelir veya yalnız tek bir kirlilik ölçütüyle karar vermek, sistemin diğer mekânsal ve toplumsal etkilerini görmezden gelir.',{type:'cycle',title:'Kaynak kullanımında döngü',items:['Tasarım','Üretim','Kullanım','Onarım/Yeniden kullanım','Geri dönüşüm']});
  add('Felsefe Grubu ve Din Kültürü','Bilgi, Varlık ve Ahlak Felsefesi','Felsefe kavramları açıklığa kavuşturur, varsayımları sorgular ve görüşleri gerekçeleriyle karşılaştırır. Bilgi felsefesi bilginin kaynağı, imkânı ve sınırını; varlık felsefesi var olanın temel yapısını; ahlak felsefesi iyi eylemin ölçütünü inceler. Akılcılık, deneycilik ve eleştiricilik bilgi kaynağına farklı ağırlıklar verir. Ahlakta ödev, sonuç ve erdem odaklı yaklaşımlar aynı olayı farklı sorularla değerlendirebilir. Sınavda filozof adından önce temel iddia, gerekçe ve karşı çıktığı görüş bulunmalıdır.',['Epistemoloji|Bilginin kaynağı, doğruluğu ve sınırlarını inceler.','Ontoloji|Varlığın ne olduğu ve temel yapısı üzerine düşünür.','Etik|Eylemlerin iyi, doğru ve sorumlu olma ölçütlerini sorgular.','Argüman|Bir sonucu desteklemek için sunulan öncüller bütünüdür.'],'“Bilginin ham maddesi deneyden gelir; fakat zihin bu veriyi kendi formlarıyla düzenler” görüşünü nasıl sınıflandırırsın?',['Görüş deneyin bilgi için gerekli olduğunu kabul eder.','Zihnin etkin düzenleyici rolünü de eklediği için yalnız deneycilik değildir.','Akıl ile deneyin katkısını birleştiren eleştirici yaklaşım çizgisine yerleştirilir.'],'Bir görüşü yalnız filozof adı ezberiyle seçmek, parçada aynı kavramın farklı gerekçeyle kullanılmasını kaçırabilir.',{type:'compare',title:'Bilginin kaynağına yaklaşımlar',items:['Akılcılık: akıl','Deneycilik: deney','Eleştiricilik: deney + zihnin yapısı']});
  add('Felsefe Grubu ve Din Kültürü','Psikoloji ve Sosyoloji','Psikoloji davranış ve zihinsel süreçleri birey düzeyinde bilimsel yöntemle inceler; sosyoloji toplumsal ilişki, kurum ve yapı örüntülerine odaklanır. Deney, gözlem, anket ve görüşme yöntemlerinin her biri farklı soru ve sınırlılıklara sahiptir. Öğrenme klasik koşullanma, edimsel koşullanma ve gözlem yoluyla açıklanabilir. Sosyalleşme bireyin kültürel norm ve rolleri edinme sürecidir; aile, eğitim, ekonomi, din ve siyaset gibi kurumlar toplumsal gereksinimlere düzenli karşılıklar üretir. Bireysel ve toplumsal açıklamalar birbirini dışlamak zorunda değildir.',['Bağımsız değişken|Araştırmacının etkisini sınadığı değişkendir.','Pekiştirme|Bir davranışın tekrar olasılığını artıran sonuçtur.','Sosyalleşme|Norm, değer ve rollerin öğrenilme sürecidir.','Toplumsal kurum|Kalıcı ihtiyaçları karşılayan düzenli ilişki örüntüsüdür.'],'Bir öğrencinin alkış aldığı için sunum yapmaya daha sık gönüllü olmasını psikoloji; sınıfta sunumun değer görmesini sosyoloji açısından açıkla.',['Alkış sonrası gönüllülüğün artması, davranışı güçlendiren olumlu pekiştirme olarak yorumlanır.','Sınıfın sunuma verdiği değer, grup normu ve eğitim kurumunun beklentileriyle ilgilidir.','Aynı olay bireysel öğrenme ve toplumsal norm düzeylerinde tamamlayıcı biçimde açıklanabilir.'],'Her ödülü pekiştireç saymak yanlıştır; sonuç davranışın tekrarını artırmıyorsa işlevsel olarak pekiştirme değildir.',{type:'compare',title:'İki analiz ölçeği',items:['Psikoloji: birey ve davranış','Sosyoloji: grup ve kurum','Ortak olay: farklı açıklama düzeyleri']});
  add('Felsefe Grubu ve Din Kültürü','Mantık','Mantık, düşüncenin içerikten bağımsız biçimsel doğruluğunu inceler. Önerme doğru veya yanlış değer alabilen yargıdır. Bir çıkarımda öncüller sonucu destekler; geçerlilik, öncüller doğru kabul edildiğinde sonucun yanlış olmasının mümkün olmamasıyla ilgilidir. Sağlam çıkarım hem geçerli biçime hem doğru öncüllere sahiptir. Tutarlılık, önermeler kümesinin aynı anda doğru olabilmesi; çelişki ise bir önerme ile değillemesinin birlikte ileri sürülmesidir. Doğruluk tablosu bileşik önermelerin bütün olasılıklarını sistemli gösterir.',['Önerme|Doğruluk değeri taşıyan yargıdır.','Geçerlilik|Öncüller ile sonuç arasındaki zorunlu biçim ilişkisidir.','Sağlamlık|Geçerli çıkarım ve doğru öncüllerin birleşimidir.','Tutarlılık|Bir önerme kümesinde birlikte doğruluğun mümkün olmasıdır.'],'“Eğer çalışırsam ilerlerim. Çalışıyorum. Öyleyse ilerlerim.” çıkarımının biçimini değerlendir.',['p: çalışıyorum, q: ilerliyorum olarak sembolleştirilir.','Öncüller p→q ve p, sonuç q biçimindedir.','Bu modus ponens adlı geçerli çıkarım biçimidir; gerçek dünyadaki öncül doğruluğu ayrıca incelenebilir.'],'Sonucun gerçekte doğru olmasını çıkarımın geçerli olduğuna kanıt saymak yanlıştır; geçerlilik öncül-sonuç biçimine bağlıdır.',{type:'flow',title:'Modus ponens',items:['p → q','p','∴ q']});
  add('Felsefe Grubu ve Din Kültürü','Din, Ahlak ve Güncel Meseleler','Din ve ahlak konuları; inanç, ibadet, değer, sorumluluk ve toplumsal hayat ilişkisi içinde ele alınır. İslam düşüncesinde Kur’an ve sünnet temel kaynaklardır; yorum gelenekleri tarihsel ve yöntemsel farklılıklar gösterebilir. Güncel bir mesele değerlendirilirken insan onuru, adalet, güven, mahremiyet, canın ve çevrenin korunması, kul hakkı ve ölçülülük gibi ilkeler birlikte düşünülmelidir. Yeni teknoloji veya toplumsal durum için yalnız benzerlik kurmak yetmez; amaç, muhtemel yarar-zarar, haklar ve güvenilir bilgi de değerlendirilmelidir.',['Ahlaki sorumluluk|İrade, niyet, bilgi ve eylemin sonuçlarıyla ilişkilidir.','Adalet|Hakkı gözetme ve ölçülü davranma ilkesidir.','Mahremiyet|Kişinin özel alanı ve bilgisinin korunmasıdır.','Yorum|Temel kaynakları yöntem ve bağlam içinde anlama çabasıdır.'],'Bir eğitim uygulamasının öğrenci verilerini açık onay olmadan paylaşmasını ahlaki ilkelerle değerlendir.',['Bilginin kişiye ait özel alan olduğu ve mahremiyet ilkesi belirlenir.','Açık onay, amaçla sınırlı kullanım ve veri güvenliği emanet/güven sorumluluğuyla ilişkilendirilir.','Eğitsel yarar iddiası tek başına hak ihlalini meşrulaştırmaz; adalet, zarar vermeme ve şeffaflık birlikte aranır.'],'Güncel meselede yalnız sonuç yararlı görünüyor diye niyet, yöntem, hak ve zarar boyutlarını yok saymak eksik değerlendirmedir.',{type:'flow',title:'Güncel meseleyi değerlendirme',items:['Güvenilir bilgi','Niyet ve amaç','Haklar','Yarar-zarar','Adaletli karar']});
